def poly(xs, x):
    return sum(coeff * math.pow(x, i) for i, coeff in enumerate(xs))

def find_zero(xs):
    x = 0.0
    tolerance = 1e-6
    max_iter = 1000
    for _ in range(max_iter):
        fx = poly(xs, x)
        if abs(fx) < tolerance:
            return x
        # Compute the derivative
        derivative_value = 0.0
        for i in range(1, len(xs)):
            coeff = xs[i]
            term = i * coeff * (x ** (i-1))
            derivative_value += term
        x_new = x - fx / derivative_value
        x = x_new
    return x

