def find_zero(xs):
    x = 0.0
    tolerance = 1e-6
    max_iterations = 1000
    for _ in range(max_iterations):
        # Evaluate the polynomial at current x
        fx = poly(xs, x)
        # Compute the derivative
        if len(xs) == 1:
            f_prime = 0.0
        else:
            f_prime = 0.0
            for i in range(1, len(xs)):
                coeff = xs[i]
                f_prime += i * coeff * (x ** (i-1))
        # Avoid division by zero
        if f_prime == 0:
            break
        # Calculate the next x using Newton-Raphson formula
        x_next = x - fx / f_prime
        # Check for convergence
        if abs(x_next - x) < tolerance:
            return x_next
        x = x_next
    # Return the last computed x if convergence is not achieved
    return x

