def poly(xs: list, x: float):
    return sum(coeff * (x ** i) for i, coeff in enumerate(xs))

def bisection(xs: list, a: float, b: float) -> float:
    if a >= b:
        a, b = b, a
    fa = poly(xs, a)
    fb = poly(xs, b)
    if fa * fb >= -1e-10:
        return None
    for _ in range(100):
        c = (a + b) / 2
        fc = poly(xs, c)
        if abs(fc) < 1e-10:
            return c
        if fa * fc < 0:
            b = c
        else:
            a = c
    return (a + b) / 2

