def poly_derivative(xs, x):
    derivative = 0
    for i in range(1, len(xs)):
        derivative += i * xs[i] * math.pow(x, i-1)
    return derivative

def find_zero(xs):
    sum_poly = sum(xs)
    if sum_poly == 0:
        return 1.0
    x = 0.0
    epsilon = 1e-6
    max_iterations = 1000
    for _ in range(max_iterations):
        f = poly(xs, x)
        f_prime = poly_derivative(xs, x)
        if abs(f) < epsilon:
            return x
        x_new = x - f / f_prime
        x = x_new
    return x

