def count_up_to(n):
    if n < 2:
        return []

    # Sieve of Eratosthenes to find primes up to n-1
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n : i] = [False] * len(sieve[i*i : n : i])

    primes = [i for i, is_p in enumerate(sieve) if is_p]
    return primes[:n]

